        <h3>Burden Composition by Income Group</h3>
        <p class="insight-text">Low-income nations remain burdened by communicable diseases, while higher income groups are entirely NCD-dominated.</p>
        <div class="chart-container" style="height: 400px;">
          <canvas id="incomeGroupChart" role="img" aria-label="100% stacked bar chart showing DALY proportions by income group"></canvas>
        </div>
      </section>
    </div>
  </main>

  <script>
    Chart.defaults.animation = false;
    Chart.defaults.font.family = 'Inter';
    Chart.defaults.color = '#475569';

    var cComm = '#e11d48';
    var cNcd = '#2563eb';
    var cInj = '#f59e0b';
    var borderGrid = 'rgba(0,0,0,0.06)';

    document.addEventListener('DOMContentLoaded', function() {

      // 1. Global Totals Chart (Stacked Bar comparing 1990 and 2024)
      var ctx1 = document.getElementById('globalTotalsChart').getContext('2d');
      new Chart(ctx1, {
        type: 'bar',
        data: {
          labels: ['1990', '2024'],
          datasets: [
            { label: 'Communicable', data: [1128.4, 612.5], backgroundColor: cComm, borderRadius: {topLeft: 0, topRight: 0, bottomLeft: 4, bottomRight: 4} },
            { label: 'NCDs', data: [768.2, 1487.3], backgroundColor: cNcd },
            { label: 'Injuries', data: [253.7, 308.6], backgroundColor: cInj, borderRadius: {topLeft: 4, topRight: 4, bottomLeft: 0, bottomRight: 0} }
          ]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          plugins: { 
            legend: { display: false },
            tooltip: { enabled: true, padding: 12, cornerRadius: 8, titleFont: {size: 14}, bodyFont: {size: 14} }
          },
          scales: {
            x: { stacked: true, grid: { display: false }, ticks: { font: {size: 16, weight: 'bold'} } },
            y: { stacked: true, grid: { color: borderGrid }, title: { display: true, text: 'Millions of DALYs', font: {size: 14} }, ticks: {font: {size: 14}} }
          },
          layout: { padding: {top: 20} }
        }
      });

      // 2. Income Group Chart (100% Stacked Bar)
      var ctx2 = document.getElementById('incomeGroupChart').getContext('2d');
      new Chart(ctx2, {
        type: 'bar',
        data: {
          labels: ['Low 1990', 'Low 2024', 'L-Mid 1990', 'L-Mid 2024', 'U-Mid 1990', 'U-Mid 2024', 'High 1990', 'High 2024'],
          datasets: [
            { label: 'Communicable (%)', data: [71.2, 52.8, 52.4, 27.1, 28.7, 11.3, 8.3, 4.1], backgroundColor: cComm, borderRadius: {topLeft: 0, topRight: 0, bottomLeft: 4, bottomRight: 4} },
