            { label: 'Injuries (%)', data: [9.0, 9.8, 11.5, 12.4, 14.0, 11.5, 10.1, 8.1], backgroundColor: cInj, borderRadius: {topLeft: 4, topRight: 4, bottomLeft: 0, bottomRight: 0} }
          ]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          plugins: { legend: { display: false }, tooltip: { enabled: true, padding: 12, cornerRadius: 8, callbacks: { label: function(c) { return c.dataset.label + ': ' + c.raw + '%'; } } } },
          scales: {
            x: { stacked: true, grid: { display: false }, ticks: { font: {size: 13} } },
            y: { stacked: true, min: 0, max: 100, grid: { color: borderGrid }, title: { display: true, text: '% Share of Total DALYs', font: {size: 14} }, ticks: { font: {size: 14}, callback: function(val){return val+'%';} } }
          },
          layout: { padding: {top: 10} }
        }
      });

      // 3. Slope Chart for Top 10 Causes Rank Change
      var slopeData = [
        { label: 'Lower respiratory infections', c: cComm, data: [1, 6] },
        { label: 'Diarrheal diseases', c: cComm, data: [2, 11] },
        { label: 'Neonatal preterm birth', c: cComm, data: [3, 5] },
        { label: 'Ischemic heart disease', c: cNcd, data: [4, 1] },
        { label: 'Stroke', c: cNcd, data: [5, 2] },
        { label: 'Malaria', c: cComm, data: [6, 11] },
        { label: 'Tuberculosis', c: cComm, data: [7, 11] },
        { label: 'Measles', c: cComm, data: [8, 11] },
        { label: 'COPD', c: cNcd, data: [9, 4] },
        { label: 'Road injuries', c: cInj, data: [10, 9] },
        { label: 'Diabetes mellitus', c: cNcd, data: [11, 3] },
        { label: 'Low back pain', c: cNcd, data: [11, 7] },
        { label: 'Depressive disorders', c: cNcd, data: [11, 8] },
        { label: 'Lung cancer', c: cNcd, data: [11, 10] }
      ];

      var slopeDatasets = slopeData.map(function(item) {
        return {
          label: item.label,
          data: item.data,
          borderColor: item.c,
          backgroundColor: item.c,
          borderWidth: 4,
          pointRadius: 6,
          pointHoverRadius: 8,
          tension: 0, // straight lines
        };
      });

      var ctx3 = document.getElementById('slopeChart').getContext('2d');
      new Chart(ctx3, {
        type: 'line',
        data: {
          labels: ['1990', '2024'],
          datasets: slopeDatasets
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          layout: { padding: { left: 40, right: 240, top: 40, bottom: 40 } },
          plugins: { 
            legend: { display: false },
            tooltip: { enabled: true, padding: 12 },
          },
          scales: {
            x: { 
              grid: { color: borderGrid, drawBorder: false }, 
              ticks: { font: {size: 18, weight: 'bold'}, padding: 16 } 
            },
            y: { 
              reverse: true, min: 1, max: 11, 
              grid: { display: false },
              title: { display: true, text: 'Global Rank', font: {size: 16, weight: '600'} },
              ticks: { 
                stepSize: 1, font: {size: 16, weight: 'bold'},
                callback: function(value) { return value === 11 ? '>10' : value; }
              }
            }
          },
          animation: {
            onComplete: function() {
              var chart = this;
              var ctx = chart.ctx;
              ctx.font = '600 15px Inter';
              ctx.textAlign = 'left';
              ctx.textBaseline = 'middle';

              chart.data.datasets.forEach(function(ds, i) {
                var meta = chart.getDatasetMeta(i);
                if (meta.hidden) return;

                // Draw label at the right side (2024 point)
                var p2024 = meta.data[1];
                if (p2024 && ds.data[1] <= 10) {
                  ctx.fillStyle = ds.borderColor;
                  ctx.fillText(ds.label, p2024.x + 12, p2024.y);
                }

                // Draw label at the left side for causes that dropped out (1990 point)
                var p1990 = meta.data[0];
                if (p1990 && ds.data[1] === 11) {
                  ctx.textAlign = 'right';
                  ctx.fillStyle = ds.borderColor;
                  ctx.fillText(ds.label, p1990.x - 12, p1990.y);
                  ctx.textAlign = 'left'; // reset
                }
              });
            }
          }
        }
      });
    });
  </script>
</body>
</html>
